mapper.select:
( select p.post_id as contentId, 'post' as contentType, pt.name as contentName, p.title as contentTitle, p.content as contentText, p.write_date as writeDate, u.nickname as writerNickname, (p.report > 0) as isReported, false as isReportedByMe from post p join post_type pt on p.post_type = pt.no join user u on p.writer_id = u.user_id where p.writer_id = #{userId} and p.report = 0
and p.title like concat('%', #{title}, '%')
and p.write_date >= #{startDate}
and p.write_date <= #{endDate}
) union all ( select c.comment_id as contentId, case when c.recomment_check = 0 then 'comment' else 'reply' end as contentType, pt.name as contentName, p.title as contentTitle, c.content as contentText, c.write_date as writeDate, u.nickname as writerNickname, (c.report > 0) as isReported, false as isReportedByMe from comment c join post p on c.post_id = p.post_id join post_type pt on p.post_type = pt.no join user u on c.writer_id = u.user_id where c.writer_id = #{userId} and c.report = 0
and p.title like concat('%', #{title}, '%')
and c.write_date >= #{startDate}
and c.write_date <= #{endDate}
)
union all ( select l.lecture_id as contentId, 'lectureRequests' as contentType, null as contentName, l.name as contentTitle, null as contentText, l.upload_date as writeDate, u.nickname as writerNickname, false as isReported, false as isReportedByMe from lecture l join lecture_status ls on l.lecture_status = ls.no join user u on l.uploader_id = u.user_id where l.uploader_id = #{userId} and l.lecture_status = 2
and l.name like concat('%', #{title}, '%')
and l.upload_date >= #{startDate}
and l.upload_date <= #{endDate}
)
union all ( select rv.review_id as contentId, 'review' as contentType, null as contentName, l.name as contentTitle, rv.content as contentText, rv.write_date as writeDate, u.nickname as writerNickname, (rv.report > 0) as isReported, false as isReportedByMe from review rv join lecture l on rv.lecture_id = l.lecture_id join user u on rv.writer_id = u.user_id where rv.writer_id = #{userId} and rv.report = 0
and l.name like concat('%', #{title}, '%')
and rv.write_date >= #{startDate}
and rv.write_date <= #{endDate}
)

( select p.post_id as contentId, 'post' as contentType, pt.name as contentName, p.title as contentTitle, pr.content as contentText, p.write_date as writeDate, u.nickname as writerNickname, True as isReportedByMe, false as isReported from post_report pr join post p on pr.post_id = p.post_id join post_type pt on p.post_type = pt.no join user u on pr.report_user_id = u.user_id where pr.report_user_id = #{userId}
AND p.title LIKE CONCAT('%', #{title}, '%')
AND p.write_date >= #{startDate}
AND p.write_date <= #{endDate}
) union all ( select c.comment_id as contentId, case when c.recomment_check = 0 then 'comment' when c.recomment_check = 1 then 'reply' End as contentType, pt.name as contentName, p.title as contentTitle, cr.content as contentText, c.write_date as writeDate, u.nickname as writerNickname, True as isReportedByMe, false as isReported from comment c join comment_report cr on c.comment_id = cr.comment_id join post p on p.post_id = c.post_id join post_type pt on p.post_type = pt.no join user u on c.writer_id = u.user_id where c.writer_id = #{userId}
AND p.title LIKE CONCAT('%', #{title}, '%')
AND c.write_date >= #{startDate}
AND c.write_date <= #{endDate}
) union all ( select rv.review_id as contentId, 'review' as contentType, null as contentName, rv.content as contentTitle, rp.content as contentText, rv.write_date as writeDate, u.nickname as writerNickname, true as isReportedByMe, false as isReported from lecture l join review rv on l.lecture_id = rv.lecture_id join review_report rp on rv.review_id = rp.review_id join user u on rp.report_user_id = u.user_id where rp.report_user_id = #{userId}
AND rv.content LIKE CONCAT('%', #{title}, '%')
AND rv.write_date >= #{startDate}
AND rv.write_date <= #{endDate}
)

(SELECT p.post_id AS contentId, 'post' AS contentType, pt.name AS contentName, p.title AS contentTitle, p.content AS contentText, p.write_date AS writeDate, u.nickname AS writerNickname, true AS isReported, false AS isReportedByMe FROM post p JOIN post_type pt ON p.post_type = pt.no JOIN user u ON p.writer_id = u.user_id WHERE p.writer_id = #{userId} AND EXISTS (SELECT 1 FROM post_report pr WHERE pr.post_id = p.post_id)
AND p.title LIKE CONCAT('%', #{title}, '%')
AND p.write_date >= #{startDate}
AND p.write_date <= #{endDate}
)
union all ( select c.comment_id AS contentId, case when c.recomment_check = 0 then 'comment' when c.recomment_check = 1 then 'reply' End as contentType, pt.name AS contentName, p.title AS contentTitle, c.content AS contentText, c.write_date AS writeDate, u.nickname AS writerNickname, true AS isReported, false AS isReportedByMe from comment c join post p on c.post_id = p.post_id join post_type pt on p.post_type = pt.no join user u on c.writer_id = u.user_id join comment_report cr on c.comment_id = cr.comment_id where c.writer_id = #{userId} and exists (select 1 from comment_report cr where cr.comment_id = c.comment_id)
AND p.title LIKE CONCAT('%', #{title}, '%')
AND c.write_date >= #{startDate}
AND c.write_date <= #{endDate}
) union all (select r.review_id AS contentId, 'review' AS contentType, null AS contentName, l.name AS contentTitle, r.content AS contentText, r.write_date AS writeDate, u.nickname AS writerNickname, true AS isReported, false AS isReportedByMe from review r join lecture l on l.lecture_id = r.lecture_id join review_report rp on r.review_id = rp.review_id join user u on r.writer_id = u.user_id where r.writer_id = #{userId} and exists (select 1 from review_report rp where rp.review_id = r.review_id)
AND l.name LIKE CONCAT('%', #{title}, '%')
AND r.write_date >= #{startDate}
AND r.write_date <= #{endDate}
)
